import { PlaneGeometry, Mesh, Group, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = config.id || 'journal-card-2';

  const ownedGeometries = [];
  const ownedMaterials = [];
  const animationHandles = [];
  const primitiveResults = [];

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const vertical = uv().y;
  const darkGradient = mix(
    color('#0b0b10'),
    color('#16161d'),
    smoothstep(0.05, 0.9, vertical)
  );
  backdropMaterial.colorNode = mix(
    darkGradient,
    color('#ff2a38'),
    smoothstep(0.84, 1.0, vertical).mul(0.045)
  );
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'journal-card-backdrop';
  backdrop.position.z = -2.5;
  root.add(backdrop);
  ownedGeometries.push(backdropGeometry);
  ownedMaterials.push(backdropMaterial);

  const shadowGeometry = new PlaneGeometry(3.5, 0.32);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.name = 'journal-card-contact-shadow';
  shadow.position.set(0, -1.08, -0.02);
  shadow.scale.x = 1.15;
  root.add(shadow);
  ownedGeometries.push(shadowGeometry);
  ownedMaterials.push(shadowMaterial);

  const cardVisual = new Group();
  cardVisual.name = 'journal-card-visual';
  root.add(cardVisual);

  const cardGeometry = new PlaneGeometry(3.2, 2.0);
  const cardMaterial = new MeshBasicNodeMaterial({ color: '#e8ecf2' });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'journal-card-image';
  cardVisual.add(card);
  ownedGeometries.push(cardGeometry);
  ownedMaterials.push(cardMaterial);

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      cardMaterial.colorNode = texture(loadedTexture);
      cardMaterial.needsUpdate = true;
    });
  }

  const labelGeometry = new PlaneGeometry(3.0, 0.54);
  const labelMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.94
  });
  const label = new Mesh(labelGeometry, labelMaterial);
  label.name = 'journal-card-label-panel';
  label.position.set(0, -0.62, 0.035);
  cardVisual.add(label);
  ownedGeometries.push(labelGeometry);
  ownedMaterials.push(labelMaterial);

  const edgeGeometry = new PlaneGeometry(0.045, 1.9);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.2
  });
  const accentEdge = new Mesh(edgeGeometry, edgeMaterial);
  accentEdge.name = 'journal-card-focus-edge';
  accentEdge.position.set(-1.52, 0, 0.045);
  cardVisual.add(accentEdge);
  ownedGeometries.push(edgeGeometry);
  ownedMaterials.push(edgeMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = typeof item.text === 'string' ? item.text : '';
    if (!text) continue;

    const textObject = ctx.fontAtlas.createText(text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });
    textObject.name = item.role || 'journal-card-headline';
    textObject.position.set(-1.32, -0.72, 0.07);
    cardVisual.add(textObject);
  }

  const focusIn = () => {
    const tween = gsap.to(edgeMaterial, {
      opacity: 0.95,
      duration: 0.3,
      ease: 'power2.out'
    });
    animationHandles.push(tween);
  };

  const focusOut = () => {
    const tween = gsap.to(edgeMaterial, {
      opacity: 0.2,
      duration: 0.3,
      ease: 'power2.out'
    });
    animationHandles.push(tween);
  };

  const hoverIn = () => {
    const tween = gsap.to(cardVisual.position, {
      y: 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
    animationHandles.push(tween);
  };

  const hoverOut = () => {
    const tween = gsap.to(cardVisual.position, {
      y: 0,
      duration: 0.7,
      ease: 'power3.out'
    });
    animationHandles.push(tween);
  };

  const click = () => {
    const press = gsap.timeline();
    press
      .to(cardVisual.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      })
      .to(cardVisual.scale, {
        x: 1,
        y: 1,
        duration: 0.42,
        ease: 'back.out(2)'
      });
    animationHandles.push(press);
    ctx.emit('hub-journal.select', {
      id: config.id || 'journal-card-2',
      source: 'journal-card-2'
    });
  };

  root.userData.handlers = {
    hover: hoverIn,
    hoverStart: hoverIn,
    hoverEnd: hoverOut,
    focus: focusIn,
    blur: focusOut,
    click
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const result = ctx.primitives[primitive.name](
      root,
      primitive.params ?? {}
    );
    if (result) primitiveResults.push(result);
  }

  root.userData.cleanup = () => {
    for (const handle of animationHandles) {
      if (handle && typeof handle.kill === 'function') handle.kill();
    }

    for (const result of primitiveResults) {
      if (result && typeof result.cleanup === 'function') result.cleanup();
      if (result?.timeline && typeof result.timeline.kill === 'function') {
        result.timeline.kill();
      }
    }

    for (const material of ownedMaterials) {
      material.dispose();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose();
    }

    root.traverse((object) => {
      if (object !== root && object.userData?.cleanup) {
        object.userData.cleanup();
      }
    });
  };

  return root;
}
